import{_ as r,c as a,o as t,ag as o}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Quick DFP Guide","description":"","frontmatter":{"title":"Quick DFP Guide"},"headers":[],"relativePath":"general/quick-dfp-guide.md","filePath":"general/quick-dfp-guide.md","lastUpdated":null}'),i={name:"general/quick-dfp-guide.md"};function l(n,e,s,h,c,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="quick-dfp-guide" tabindex="-1">Quick DFP Guide <a class="header-anchor" href="#quick-dfp-guide" aria-label="Permalink to &quot;Quick DFP Guide&quot;">​</a></h1><h2 id="privacy-resources" tabindex="-1">Privacy Resources <a class="header-anchor" href="#privacy-resources" aria-label="Permalink to &quot;Privacy Resources&quot;">​</a></h2><p>👀 Looking for a list of Guides and Checklists? See the <a href="/general/dfp-guide.html">Force Protection Guide here</a>.</p><h3 id="community-generated" tabindex="-1">Community Generated <a class="header-anchor" href="#community-generated" aria-label="Permalink to &quot;Community Generated&quot;">​</a></h3><ul><li><a href="https://github.com/irregularchat/public-resources/tree/main/Checklists" target="_blank" rel="noreferrer">Community DFP Checklists</a></li><li><a href="https://github.com/Lissy93/awesome-privacy" target="_blank" rel="noreferrer">Awesome Privacy Repo</a></li><li><a href="https://anonymousplanet.org/export/guide.pdf" target="_blank" rel="noreferrer">Anonymous World Guide</a> (<a href="https://github.com/orgs/irregularchat/discussions/18#discussioncomment-7215054" target="_blank" rel="noreferrer">source</a>)</li><li><a href="https://inteltechniques.com/data/workbook.pdf" target="_blank" rel="noreferrer">Extreme Privacy: Workbook</a></li><li><a href="https://privacyguides.org/tools/" target="_blank" rel="noreferrer">Privacy Guides</a></li><li><a href="https://inteltechniques.com/links.html" target="_blank" rel="noreferrer">IntelTechniques Guides</a></li><li><a href="https://www.privacytools.io/" target="_blank" rel="noreferrer">Privacy Tools</a></li><li><a href="https://book.hashbang.sh/" target="_blank" rel="noreferrer">HashBang Book</a></li><li><a href="https://firewallsdontstopdragons.com/resources/" target="_blank" rel="noreferrer">Firewalls Don&#39;t Stop Dragons Resources</a></li><li><a href="https://spreadprivacy.com/tag/device-privacy-tips/" target="_blank" rel="noreferrer">DuckDuckGo Privacy Guide</a></li></ul><h3 id="communities" tabindex="-1">Communities <a class="header-anchor" href="#communities" aria-label="Permalink to &quot;Communities&quot;">​</a></h3><ul><li><a href="https://www.reddit.com/r/privacy/" target="_blank" rel="noreferrer">r/Privacy</a></li><li><a href="https://matrix.to/#/#privacyguides:matrix.org" target="_blank" rel="noreferrer">Privacy Guides Matrix</a></li></ul><hr><h2 id="privacy-security-tools" tabindex="-1">Privacy &amp; Security Tools <a class="header-anchor" href="#privacy-security-tools" aria-label="Permalink to &quot;Privacy &amp; Security Tools&quot;">​</a></h2><h3 id="pre-browsing-checks" tabindex="-1">Pre-Browsing Checks <a class="header-anchor" href="#pre-browsing-checks" aria-label="Permalink to &quot;Pre-Browsing Checks&quot;">​</a></h3><p>Check to confirm your configuration and VPN:</p><ol><li><a href="https://dnsleaktest.com/" target="_blank" rel="noreferrer">DNS / IP Leak Test</a> - Confirm your location is what you want it to be</li><li><a href="https://coveryourtracks.eff.org/" target="_blank" rel="noreferrer">Cover Your Tracks (EFF)</a> - Check browser fingerprinting</li><li><a href="https://www.grc.com/cookies/forensics.html" target="_blank" rel="noreferrer">Browser Cookie Tester</a></li><li><a href="https://inappbrowser.com/" target="_blank" rel="noreferrer">InAppBrowser</a></li><li><a href="https://canyoublockit.com/extreme-test/" target="_blank" rel="noreferrer">AdBlock Test</a> - Verify your adblocker or DNS is blocking ads</li></ol><h3 id="password-manager" tabindex="-1">Password Manager <a class="header-anchor" href="#password-manager" aria-label="Permalink to &quot;Password Manager&quot;">​</a></h3><p>See the <a href="/general/guide-to-password-managers.html">Password Manager Section</a>.</p><ul><li><strong>Bitwarden</strong> (<a href="https://apps.apple.com/us/app/bitwarden-password-manager/id1137397744" target="_blank" rel="noreferrer">iOS</a> | <a href="https://play.google.com/store/apps/details?id=com.x8bit.bitwarden&amp;hl=en_US&amp;gl=US" target="_blank" rel="noreferrer">Android</a> | <a href="https://bitwarden.com/download/" target="_blank" rel="noreferrer">Windows, Mac, Linux</a> | <a href="https://bitwarden.com/" target="_blank" rel="noreferrer">Web (Works on NIPR)</a>)</li><li><strong>KeePass</strong> (<a href="https://keepassium.com/" target="_blank" rel="noreferrer">iOS</a> | <a href="https://www.keepassdx.com/" target="_blank" rel="noreferrer">Android</a> | <a href="https://keepassxc.org/download/" target="_blank" rel="noreferrer">Windows, Mac, Linux</a> | <a href="https://app.keeweb.info/" target="_blank" rel="noreferrer">Web (Works on NIPR)</a>)</li></ul><h4 id="password-managers-to-avoid" tabindex="-1">Password Managers to Avoid <a class="header-anchor" href="#password-managers-to-avoid" aria-label="Permalink to &quot;Password Managers to Avoid&quot;">​</a></h4><ul><li>LastPass</li></ul><h3 id="multi-factor-authentication-mfa" tabindex="-1">Multi-Factor Authentication (MFA) <a class="header-anchor" href="#multi-factor-authentication-mfa" aria-label="Permalink to &quot;Multi-Factor Authentication (MFA)&quot;">​</a></h3><ul><li><a href="https://www.yubico.com/product/security-key-c-nfc-by-yubico/" target="_blank" rel="noreferrer">Cheapest 2FA YubiKey</a> (Hardware U2F is BEST)</li><li><strong>2FAS</strong> (<a href="https://apps.apple.com/us/app/2fas-auth/id1217793794" target="_blank" rel="noreferrer">iOS</a> | <a href="https://play.google.com/store/apps/details?id=com.twofasapp" target="_blank" rel="noreferrer">Android</a> | <a href="https://2fas.com/browser-extension/" target="_blank" rel="noreferrer">Chrome Extension</a>)</li><li><strong>OTP Auth</strong> (<a href="https://apps.apple.com/us/app/otp-auth/id659877384" target="_blank" rel="noreferrer">iOS</a>)</li><li><strong>Aegis</strong> (<a href="https://getaegis.app/" target="_blank" rel="noreferrer">Android</a>)</li><li><strong>Authenticator</strong> (<a href="https://addons.mozilla.org/en-US/firefox/addon/auth-helper/" target="_blank" rel="noreferrer">Firefox</a>)</li></ul><h4 id="authenticators-to-avoid" tabindex="-1">Authenticators to Avoid <a class="header-anchor" href="#authenticators-to-avoid" aria-label="Permalink to &quot;Authenticators to Avoid&quot;">​</a></h4><ul><li><strong>SMS</strong> - Vulnerable to SIM-jacking attacks</li><li><strong>Authy</strong> - Requires phone number, not open-source</li><li><strong>Google Authenticator</strong> - Sync is not E2EE</li></ul><h3 id="vpn" tabindex="-1">VPN <a class="header-anchor" href="#vpn" aria-label="Permalink to &quot;VPN&quot;">​</a></h3><p>Full VPN Guide: <a href="/privacy/vpn-recommendation.html">VPN Recommendation</a></p><p>Top VPNs for privacy and security:</p><ol><li><p><strong><a href="https://mullvad.net/en/" target="_blank" rel="noreferrer">MullvadVPN</a></strong></p><ul><li>No email association</li><li>Proven privacy record</li><li>Accepts cash/crypto</li><li>.onion available</li></ul></li><li><p><strong><a href="https://ivpn.net" target="_blank" rel="noreferrer">iVPN</a></strong></p><ul><li>No logging</li><li>Transparent privacy policy</li><li>Supports multiple protocols</li></ul></li><li><p><strong><a href="https://protonvpn.com" target="_blank" rel="noreferrer">ProtonVPN</a></strong></p><ul><li>Proven privacy record</li><li>Free tier available</li><li>Works with OpenVPN config files</li></ul></li></ol><h4 id="vpns-to-avoid" tabindex="-1">VPNs to Avoid <a class="header-anchor" href="#vpns-to-avoid" aria-label="Permalink to &quot;VPNs to Avoid&quot;">​</a></h4><ul><li>ExpressVPN</li><li>PIA VPN</li><li>CyberGhost</li><li>Zenmate</li></ul><blockquote><p><a href="https://restoreprivacy.com/kape-technologies-owns-expressvpn-cyberghost-pia-zenmate-vpn-review-sites/" target="_blank" rel="noreferrer">KAPE Technologies Owns ExpressVPN, CyberGhost, PIA, &amp; Zenmate VPN Review Sites</a></p></blockquote><h3 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h3><p>See the <a href="/general/android-virtual-device.html">Virtual Device Guide</a> for using Android Virtual Device Manager.</p><h3 id="computer-isolation" tabindex="-1">Computer Isolation <a class="header-anchor" href="#computer-isolation" aria-label="Permalink to &quot;Computer Isolation&quot;">​</a></h3><p>See the <a href="/general/virtual-environments.html">Environment Guide</a> to set up Virtual Machines for secure isolation.</p><h3 id="web" tabindex="-1">Web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;Web&quot;">​</a></h3><p>Enhance your web browsing privacy with the resources listed above.</p>',34)])])}const g=r(i,[["render",l]]);export{d as __pageData,g as default};
